steps.action:
curl -s https://api.linear.app/graphql \
  -X POST \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      issues(first: 20, filter: {
        team: { name: { eq: \"Web\" } },
        state: { name: { eq: \"Done\" } }
      }) {
        nodes {
          id
          title
          description
          priority
          state {
            name
          }
          team {
            name
          }
          project {
            name
          }
        }
      }
    }"
  }'
